/** 隔离回归：追溯、冲突双方、方法生成/运行/失效、权限与结果分离。 */
import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';
import { bodyFixture } from './memory-body-fixture.js';
process.env.EMBED_MODE='fake';process.env.MEMORYOS_EXEC_OFF='1';
const root=fs.mkdtempSync(path.join(os.tmpdir(),'memory-workflows-'));process.env.MEMORY_DB=path.join(root,'test.db');
const {openDb,writeMemory,readMemory,updateMemory}=await import('./db.js');
const {registerAllTools}=await import('./server-tools.js');
const {annotateConflicts,qualityOf,resolveEvidence,attachEvidence,conflictMap}=await import('./knowledge-quality.js');
const {generalContext}=await import('./memory-quality.js');
const {hybridSearch}=await import('./search.js');
const {runEvalSuite}=await import('./eval-suite.js');
const db=openDb(process.env.MEMORY_DB);const registry={addTool(){}};
const {tools}=registerAllTools(registry,{db,dbPath:process.env.MEMORY_DB,AGENT:'workflow-test',AGENT_FPATH:'fixture',ENV_CRED:null});
let count=0;function check(name,ok){assert.ok(ok,name);count++;console.log('通过 '+name);}
async function call(name,args){const t=tools.get(name);const r=await t.execute(t.parameters.parse(args));if(r?.isError)throw new Error(r.content[0].text);return JSON.parse(r);}
const add=(content,opts={})=>writeMemory(db,{content,type:'experience',agent:'test',agent_fpath:null,project:'test',...opts});
const fail=async(name,fn)=>{let bad=false;try{await fn();}catch{bad=true;}check(name,bad);};
try{
 const a=add(bodyFixture('workflow_probe MCP连接与内核来源核验'));
 const b=add(bodyFixture('workflow_probe 内核采用不同方法，冲突待核验'));
 const foreign=add(bodyFixture('外部范围原文'),{project:'other'}),secret=add(bodyFixture('私密原文不得泄漏'),{sensitivity:'secret'});
 const old=add(bodyFixture('历史来源'),{status:'superseded'});
 const ref={memory_id:a.id,version:a.version,quote:'workflow_probe MCP连接与内核来源核验',relation:'supports'};
 const versionBefore=a.version,confidenceBefore=a.confidence;
 const attached=await call('memory_evidence',{memory_id:b.id,project:'test',evidence:[ref]});
 check('合法原文引用可回查',attached.evidence.length===1&&attached.evidence[0].state==='reference_checked');
 check('引用不自动认证事实',attached.verification==='reference_checked'&&attached.notice.includes('不等于'));
 check('引用不改正文版本或置信度',readMemory(db,a.id).version===versionBefore&&readMemory(db,a.id).confidence===confidenceBefore);
 await call('memory_evidence',{memory_id:b.id,project:'test',evidence:[ref]});check('重复引用幂等',qualityOf(db,b.id).evidence.length===1);
 await fail('拒绝伪造原文',()=>call('memory_evidence',{memory_id:b.id,project:'test',evidence:[{...ref,quote:'这不是原文的编造证据'}]}));
 await fail('拒绝来源旧版本',()=>call('memory_evidence',{memory_id:b.id,project:'test',evidence:[{...ref,version:999}]}));
 await fail('拒绝跨项目来源',()=>call('memory_evidence',{memory_id:b.id,project:'test',evidence:[{...ref,memory_id:foreign.id}]}));
 await fail('拒绝私密来源',()=>call('memory_evidence',{memory_id:b.id,project:'test',evidence:[{...ref,memory_id:secret.id}]}));
 await fail('拒绝自引用',()=>call('memory_evidence',{memory_id:a.id,project:'test',evidence:[ref]}));
 await fail('失效来源不能作为当前支持证据',()=>call('memory_evidence',{memory_id:b.id,project:'test',evidence:[{...ref,memory_id:old.id,quote:old.content.slice(0,20)}]}));
 await call('memory_evidence',{memory_id:b.id,project:'test',evidence:[{memory_id:old.id,version:old.version,quote:old.content.slice(0,20),relation:'context'}]});
 check('历史原文只作历史上下文',qualityOf(db,b.id).evidence.some(e=>e.state==='historical_context'));
 const writeArgs={content:bodyFixture('workflow_upload 有出处的新增结论'),project:'test',evidence:[ref],idempotency_key:'write-evidence'};
 const w=tools.get('memory_write');await w.execute(w.parameters.parse(writeArgs));
 const uploaded=db.prepare('SELECT id FROM memories WHERE idempotency_key=?').get('write-evidence');check('实际上传路径原子保存引用',uploaded&&qualityOf(db,uploaded.id).evidence.length===1);
 const before=db.prepare('SELECT COUNT(*) n FROM memories').get().n;
 const badResult=await w.execute(w.parameters.parse({...writeArgs,content:bodyFixture('不应入库的假证据'),idempotency_key:'invalid-evidence',evidence:[{...ref,quote:'凭空编造且不存在的片段'}]}));
 check('坏证据拒绝且没有新增行',badResult.isError&&db.prepare('SELECT COUNT(*) n FROM memories').get().n===before);
 // 单向指针必须保护双方，普通调查检索仍可见提示。
 db.prepare('UPDATE memories SET conflict_with=? WHERE id=?').run(a.id,b.id);
 const peers=conflictMap(db,[a.id,b.id]);check('冲突关系双向可见',peers.get(a.id).includes(b.id)&&peers.get(b.id).includes(a.id));
 const ctx=generalContext(db,{project:'test',limit:50});check('默认上下文排除冲突双方',!ctx.some(r=>[a.id,b.id].includes(r.id)));
 const offline={async embedTexts(){throw new Error('词法专项');}};
 const hits=await hybridSearch(db,offline,{query:'workflow_probe',project:'test',limit:10});check('调查检索保留双方及对称提示',hits.filter(r=>[a.id,b.id].includes(r.id)).length===2&&hits.filter(r=>[a.id,b.id].includes(r.id)).every(r=>r.conflict_peers.length));
 const focused=await tools.get('memory_context').execute(tools.get('memory_context').parameters.parse({focus:'workflow_probe',project:'test',limit:10,simFloor:0,relRatio:0}));
 check('主题上下文也不把另一方当确定结论',![a.id,b.id].some(id=>new RegExp('^#'+id+' ','m').test(focused)));
 // 方法冲突核查可含争议来源，但不自动裁决。
 const conflict=await call('method_apply',{action:'generate',query:'记忆冲突核查',project:'test',source_ids:[a.id,b.id],profile:'conflict'});
 check('方法从真实来源生成，绑定编号版本与指纹',conflict.sources.length===2&&conflict.body.steps.every(s=>s.evidence.length)&&conflict.body.stop_conditions.length);
 const conflictRun=await call('method_apply',{action:'run',method_id:conflict.id,project:'test'});check('冲突核查返回双方，不自动裁决事实',conflictRun.outcome==='passed'&&conflictRun.unresolved.length===2&&conflictRun.verdict.includes('未自动裁决'));
 await fail('非调查方法不能使用未决冲突来源',()=>call('method_apply',{action:'generate',query:'MCP连接检查',project:'test',source_ids:[a.id],profile:'mcp'}));
 db.prepare('UPDATE memories SET conflict_with=NULL WHERE id=?').run(b.id);
 const m=await call('method_apply',{action:'generate',query:'MCP连接检查',project:'test',source_ids:[a.id],profile:'mcp'});
 check('完整包包含前提失败条件与恢复',m.body.prerequisites.length&&m.body.rollback&&m.body.success_criteria);
 const again=await call('method_apply',{action:'generate',query:'MCP连接检查',project:'test',source_ids:[a.id],profile:'mcp'});check('相同来源与目标生成幂等',again.id===m.id);
 const pre=await call('method_query',{action:'preflight',method_id:m.id,project:'test'});check('正确环境可以预检',pre.state==='ready');
 const countBeforeRun=db.prepare('SELECT COUNT(*) n FROM memories').get().n;
 const run=await call('method_apply',{action:'run',method_id:m.id,project:'test'});check('真实固定只读检查通过并记录审计',run.outcome==='passed'&&run.checks.some(c=>c.name==='write_schema_rejects_unstructured'&&c.ok));
 check('运行不改原记忆',db.prepare('SELECT COUNT(*) n FROM memories').get().n===countBeforeRun&&readMemory(db,a.id).content===a.content);
 const read=await call('method_query',{action:'read',method_id:m.id,project:'test'});check('检查覆盖范围明确',read.status==='checked'&&read.note.includes('只读检查'));
 const list=await call('method_query',{action:'search',query:'MCP',project:'test'});check('方法可被任务检索',list.methods.some(x=>x.id===m.id));
 await fail('方法范围隔离',()=>call('method_query',{action:'read',method_id:m.id,project:'other'}));
 const general=await call('method_apply',{action:'generate',query:'通用操作方法',project:'test',source_ids:[a.id],profile:'general'});
 await call('method_apply',{action:'feedback',method_id:general.id,project:'test',outcome:'reported_success',note:'调用方自行报告'});
 check('调用方成功报告不能认证草稿',(await call('method_query',{action:'read',method_id:general.id,project:'test'})).status==='draft');
 check('未验证通用方法不能运行',(await call('method_apply',{action:'run',method_id:general.id,project:'test'})).outcome==='not_run');
 await fail('没有来源不编造方法',()=>call('method_apply',{action:'generate',query:'缺证据',project:'test',source_ids:[999999]}));
 await fail('秘密来源不进入方法',()=>call('method_apply',{action:'generate',query:'MCP连接',project:'test',source_ids:[secret.id]}));
 await fail('来源不支持方法主题时拒绝',()=>call('method_apply',{action:'generate',query:'内核验收',project:'test',source_ids:[foreign.id]}));
 updateMemory(db,a.id,{content:bodyFixture('workflow_probe MCP来源已经修改')});
 check('正文更新使原文证据失效',qualityOf(db,b.id).evidence.some(e=>e.state==='stale'));
 const stale=await call('method_query',{action:'read',method_id:m.id,project:'test'});check('来源变化使方法失效且屏蔽缓存步骤',stale.status==='stale'&&stale.body.steps.length===0);
 check('失效方法预检明确阻断',(await call('method_query',{action:'preflight',method_id:m.id,project:'test'})).state==='stale');
 check('失效方法不继续运行',(await call('method_apply',{action:'run',method_id:m.id,project:'test'})).outcome==='not_run');
 db.prepare("UPDATE memories SET sensitivity='secret' WHERE id=?").run(a.id);const hidden=await call('method_query',{action:'read',method_id:m.id,project:'test'});
 check('来源改私密后不泄漏旧正文',!JSON.stringify(hidden).includes('workflow_probe MCP连接与内核来源核验'));
 // 评测空答案不能用固定recall=1掩盖误命中；await Promise embedder。
 db.prepare('INSERT INTO eval_queries(query,expected_ids,project) VALUES(?,?,?)').run('workflow_upload',JSON.stringify([uploaded.id]),'test');
 db.prepare('INSERT INTO eval_queries(query,expected_ids,project) VALUES(?,?,?)').run('nonexistent_xyzq9346_abef','[]','test');
 const evaluation=await runEvalSuite(db,Promise.resolve(offline));check('评测有正例与无答案分项',evaluation.total===2&&evaluation.no_answer_cases===1&&evaluation.no_answer_accuracy===1);
 db.prepare('UPDATE eval_queries SET expected_ids=? WHERE id=1').run('bad-json');await fail('坏评测标签拒绝而不是冒充无答案',()=>runEvalSuite(db,offline));

 const c1=add(bodyFixture('明确反驳来源的一条记忆'));
 const c2=add(bodyFixture('与另一记忆相关的原始主张'));
 await call('memory_evidence',{memory_id:c1.id,project:'test',evidence:[{memory_id:c2.id,version:c2.version,quote:c2.content.slice(0,30),relation:'refutes'}]});
 check('反驳证据进入现有仲裁队列',readMemory(db,c1.id).conflict_with===c2.id&&conflictMap(db,[c1.id,c2.id]).get(c2.id).includes(c1.id));
 const {applyArbitration}=await import('./db.js');applyArbitration(db,c1.id,'4');
 check('人工不冲突裁决解除引用关系并保留证据',!conflictMap(db,[c1.id,c2.id]).get(c2.id).length&&db.prepare('SELECT resolution FROM knowledge_evidence WHERE memory_id=?').get(c1.id).resolution==='reviewed_no_conflict');
 await call('memory_evidence',{memory_id:c1.id,project:'test',evidence:[{memory_id:c2.id,version:c2.version,quote:c2.content.slice(0,30),relation:'refutes'}]});
 check('重传已裁决的同一证据不重开冲突',!readMemory(db,c1.id).conflict_with&&!conflictMap(db,[c1.id,c2.id]).get(c2.id).length);
 const qv=Array(1024).fill(0);qv[0]=1;
 const gv=[...qv];gv[0]=0.95;gv[1]=Math.sqrt(1-0.95**2);
 const nv=[...qv];nv[0]=0.65;nv[1]=Math.sqrt(1-0.65**2);
 const relevant=add(bodyFixture('真正相关的证据条目'),{project:'gate-order',embedding:gv,salience:0.6});
 const noise=add(bodyFixture('高显著度但不满足证据门槛'),{project:'gate-order',embedding:nv,salience:100});
 db.prepare("UPDATE memory_vectors SET embed_model='isolated-model' WHERE memory_id IN (?,?)").run(relevant.id,noise.id);
 const supplied={provenance(){return {model:'isolated-model',dim:1024};},async embedTexts(){return [qv];}};
 const gated=await hybridSearch(db,supplied,{project:'gate-order',query:'uniqueqxbz943',limit:10,simFloor:0.8,relRatio:0.5});
 check('绝对证据不合格的高显著度条目不抬高相对门槛',gated.some(r=>r.id===relevant.id)&&!gated.some(r=>r.id===noise.id));
 check('查询出处取实际embedder而非全局fake环境',gated._searchStats.provMismatch===0);
 const {buildApp}=await import('./dashboard.js');const app=buildApp(db,{token:'workflow-test-token'});await app.ready();
 const response=await app.inject({method:'POST',url:'/v1/embeddings',headers:{'x-memory-token':'workflow-test-token'},payload:{input:['向量出处检查'],model:'client-invented-model'}});
 check('向量API拒绝fake防止污染真实语料',response.statusCode===503&&response.json().error==='embedder-fake');await app.close();
 const {serveEmbeddings}=await import('./memory-domain.js');
 const provenanceResponse=await serveEmbeddings({getEmbedder:async()=>({mode:'unit-fixture',provenance:()=>({model:'actual-model',dim:1024}),embedTexts:async texts=>texts.map(()=>qv)})},{input:['单位测试'],model:'client-invented-model'});
 check('向量API回报实际模型而非回显客户端model',provenanceResponse.model==='actual-model');
 console.log('总计 '+count+' 项通过');
}finally{db.close();}
